input.command:
cd /tmp/prcopy; cat > /tmp/t.bats <<'EOF'
@test x {
  run /tmp/prcopy/evals/harness/spend.sh --runs /tmp/prcopy/evals/tests/fixtures/ablation/spend/runs.jsonl --ledger /tmp/prcopy/evals/tests/fixtures/ablation/spend/cost-ledger.jsonl
  echo "$status $output" >&3
}
EOF
bats /tmp/t.bats

cd ~/rv; cat > neg.bats <<'EOF'
@test neg { ! true; echo reached >&3; }
EOF
bats neg.bats; bats --version

cd ~/rvtmp/wt && cat > evals/tests/zz-probe.bats <<'EOF'
load_setup() { :; }
EOF
sed -n '1,/^}/p' evals/tests/run-arms.bats | sed -n '/^setup()/,/^}/p' > /dev/null
{ sed -n '/^setup()/,/^}/p' evals/tests/run-arms.bats; sed -n '/^teardown()/,/^}/p' evals/tests/run-arms.bats; cat <<'EOF'
@test "probe: failing trials with no reported cost never move spent" {
  export EVAL_CLAUDE_BIN="$TESTS_DIR/fixtures/claude-stub.sh" STUB_EXIT=1
  run "$RA" --suite review-recall --arms baseline --fixtures pr-01 --trials 5 --concurrency 1 \
    --source-commit "$SHA" --results-dir "$RES" --retry-wait 0 --max-usd 12
  echo "status=$status" >&3
  S="$RES/review-recall/batch-pr-01-pr-01-n1/STATUS.json"
  jq -c '{state, spend, cut, per_arm}' "$S" >&3
}
EOF
} > evals/tests/zz-probe.bats
export PATH=~/rvtmp/bin:$PATH TMPDIR=~/rvtmp/tmp; timeout 600 bats evals/tests/zz-probe.bats 2>&1 | tail -5; rm evals/tests/zz-probe.bats

